        return null;
    }

    static Node build(List<String> tk) {
        if (tk.isEmpty() || tk.get(0).equals("null")) return null;
        Node root = new Node(Integer.parseInt(tk.get(0)));
        ArrayDeque<Node> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tk.size()) {
            Node node = q.poll();
            if (i < tk.size() && !tk.get(i).equals("null")) {
                node.left = new Node(Integer.parseInt(tk.get(i)));
                q.add(node.left);
            }
            i++;
            if (i < tk.size() && !tk.get(i).equals("null")) {
                node.right = new Node(Integer.parseInt(tk.get(i)));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tk = new ArrayList<>();
        String line;
        int n = 0;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) {
                String t = st.nextToken();
                tk.add(t);
                if (!t.equals("null")) n++;
            }
        }
        Node head = toDoublyList(build(tk));
        StringBuilder a = new StringBuilder(), b = new StringBuilder();
        Node cur = head;
